public protocol SappaCoreProtocol: AnyObject, Sendable {
    
    /**
     * The user opened the fine: it no longer counts as "nueva".
     */
    func acknowledgeFine(id: Int64, now: Int64) throws 
    
    func addVehicle(plate: String, kind: VehicleKind, nickname: String?, now: Int64) throws  -> Vehicle
    
    /**
     * Removes the database file and recreates an empty schema.
     */
    func deleteAll() throws 
    
    /**
     * Everything the user stored, as JSON.
     */
    func exportData(now: Int64) throws  -> String
    
    func getFine(id: Int64, now: Int64) throws  -> Fine?
    
    func getVehicle(id: Int64) throws  -> Vehicle?
    
    func health(now: Int64, limit: UInt32) throws  -> Health
    
    /**
     * Fines of one vehicle, or of all vehicles when `vehicle_id` is `None`.
     */
    func listFines(vehicleId: Int64?, now: Int64) throws  -> [Fine]
    
    func listVehicles() throws  -> [Vehicle]
    
    /**
     * The shell posted (or scheduled) these notifications.
     */
    func markAlertsDelivered(ids: [Int64], now: Int64) throws 
    
    /**
     * "Ya la pagué". Returns the ids of alerts the shell should unschedule.
     */
    func markPaid(fineId: Int64, now: Int64) throws  -> [Int64]
    
    /**
     * Undelivered, uncancelled alerts (for re-scheduling after app launch).
     */
    func pendingAlerts(now: Int64) throws  -> [Alert]
    
    /**
     * "Recordarme antes del vencimiento": (re)arms the discount-ending reminder. Returns `None`
     * when no discounted window is left.
     */
    func remindBeforeDeadline(fineId: Int64, now: Int64) throws  -> Alert?
    
    /**
     * Removes a vehicle and its fines. Returns the ids of alerts the shell should unschedule.
     */
    func removeVehicle(id: Int64) throws  -> [Int64]
    
    func renameVehicle(id: Int64, nickname: String?) throws  -> Vehicle
    
    /**
     * Runs one pass over all plates within `budget_ms`. Safe to call repeatedly; see `runner`.
     */
    func runCheck(now: Int64, trigger: CheckTrigger, budgetMs: UInt32) throws  -> CheckReport
    
    func schemaVersion() throws  -> Int64
    
    /**
     * Small JSON document for widgets/extensions, which never open the database. The shell
     * writes it to shared storage after each run and passes the next scheduled check time.
     */
    func widgetSnapshot(now: Int64, nextCheckAt: Int64?) throws  -> String
    
}
