/**
 * Something the shell should notify about, at `due_at` (now or later). The shell posts it, using
 * `sappa-alert-<id>` as the notification identifier, then calls `mark_alerts_delivered`.
 */
public struct Alert: Equatable, Hashable {
    public var id: Int64
    public var kind: AlertKind
    public var dueAt: Int64
    public var fineId: Int64?
    public var vehicleId: Int64?
    public var plate: String?
    public var nickname: String?
    public var vehicleKind: VehicleKind?
    public var infractionCode: String?
    public var place: String?
    public var amount: Int64?
    public var discountStage: DiscountStage?
    /**
     * Business days left in the 50% window, counted at `due_at`.
     */
    public var businessDaysLeft: UInt32?
    public var discountDeadline: Int64?
    /**
     * For `checks_failing`: last successful check.
     */
    public var lastOkAt: Int64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: Int64, kind: AlertKind, dueAt: Int64, fineId: Int64?, vehicleId: Int64?, plate: String?, nickname: String?, vehicleKind: VehicleKind?, infractionCode: String?, place: String?, amount: Int64?, discountStage: DiscountStage?, 
        /**
         * Business days left in the 50% window, counted at `due_at`.
         */businessDaysLeft: UInt32?, discountDeadline: Int64?, 
        /**
         * For `checks_failing`: last successful check.
         */lastOkAt: Int64?) {
        self.id = id
        self.kind = kind
        self.dueAt = dueAt
        self.fineId = fineId
        self.vehicleId = vehicleId
        self.plate = plate
        self.nickname = nickname
        self.vehicleKind = vehicleKind
        self.infractionCode = infractionCode
        self.place = place
        self.amount = amount
        self.discountStage = discountStage
        self.businessDaysLeft = businessDaysLeft
        self.discountDeadline = discountDeadline
        self.lastOkAt = lastOkAt
    }

    

    
}

