        self.id = id
        self.plate = plate
        self.kind = kind
        self.nickname = nickname
        self.createdAt = createdAt
        self.lastCheckedAt = lastCheckedAt
        self.pendingFines = pendingFines
        self.newFines = newFines
    }

    

    
